ALTER TABLE "sentence_ai_jobs" DROP CONSTRAINT "sentence_ai_jobs_kind_format";--> statement-breakpoint
ALTER TABLE "sentence_ai_jobs" ADD CONSTRAINT "sentence_ai_jobs_kind_format" CHECK (("sentence_ai_jobs"."job_kind"='sentence-generation' and (("sentence_ai_jobs"."format"='sentence-generation:v1' and "sentence_ai_jobs"."input_payload"->>'generationPolicyVersion'='1') or ("sentence_ai_jobs"."format"='sentence-generation:v2' and "sentence_ai_jobs"."input_payload"->>'generationPolicyVersion'='2'))) or ("sentence_ai_jobs"."job_kind"='sentence-check' and "sentence_ai_jobs"."format"='sentence-check:v1'));--> statement-breakpoint
ALTER TABLE "sentence_exercises" ADD CONSTRAINT "sentence_exercises_generation_policy" CHECK ("sentence_exercises"."generation_policy_version" in (1,2) and "sentence_exercises"."public_content"->>'generationPolicyVersion' = "sentence_exercises"."generation_policy_version"::text);